  try {
      if (function_exists('db_all')) {
          $dbDecidedCases = db_all("
              SELECT uc.case_id, uc.decided_category, uc.punishment_details, uc.final_decision, uc.updated_at,
                     s.program,
                     ot.name AS offense_name, ot.level AS offense_level
              FROM upcc_case uc
              JOIN upcc_case_offense uco ON uco.case_id = uc.case_id
              JOIN offense o ON o.offense_id = uco.offense_id
              JOIN offense_type ot ON ot.offense_type_id = o.offense_type_id
              LEFT JOIN student s ON s.student_id = uc.student_id
              WHERE uc.decided_category IS NOT NULL AND uc.status IN ('RESOLVED', 'CLOSED', 'DECIDED', 'FINALIZED', 'AWAITING_ADMIN_FINALIZATION')
              ORDER BY uc.updated_at DESC
          ");

          foreach ($dbDecidedCases as $dc) {
              $catNum = (int)$dc['decided_category'];
              $pun = function_exists('formatPunishmentDetails') ? formatPunishmentDetails($dc['punishment_details']) : "Category {$catNum}";
              $offLvl = strtoupper((string)($dc['offense_level'] ?? 'MAJOR'));
              $formattedLvl = (strpos($offLvl, 'MINOR') !== false) ? 'MINOR (Section 4)' : 'MAJOR';
              $staticRecords[] = [
                  'offense' => (string)($dc['offense_name'] ?? 'DISCIPLINARY OFFENSE'),
                  'level' => $formattedLvl,
                  'sanction' => "Category {$catNum} — " . ($pun !== 'n/a' ? $pun : ($dc['final_decision'] ?? 'Decision Applied'))
              ];
          }
      }
  } catch (\Throwable $e) {}

  return $staticRecords;
}

function is_shs_program($program) {
    $p = strtoupper(trim((string)$program));
    $keywords = ['SHS', 'SENIOR', 'ABM', 'STEM', 'HUMSS', 'TVL', 'GAS', 'GRADE 11', 'GRADE 12', 'G11', 'G12', 'HIGH SCHOOL'];
    foreach ($keywords as $kw) {
        if (strpos($p, $kw) !== false) return true;
    }
    return false;
}

function get_filtered_historical_records($monthStart, $monthEnd, $audience = 'ALL', $category = 'ALL') {
    $records = get_historical_dataset_records();
    $filtered = [];
    $maxAllowedDate = date('Y-m-d 23:59:59');

    foreach ($records as $r) {
        $dateStr = $r['date'] ?? '';
        if (!empty($dateStr)) {
            if ($dateStr > $maxAllowedDate) continue;
            if ($monthStart !== '1970-01-01 00:00:00') {
                if ($dateStr < $monthStart || $dateStr > $monthEnd) continue;
            }
        }

        // Audience filter
        $isShs = is_shs_program($r['program'] ?? '');
        if ($audience === 'SHS') {
            if (!$isShs) continue;
        } elseif ($audience === 'COLLEGE') {
            if ($isShs) continue;
        }

        // Category filter
        $lvl = strtoupper($r['level'] ?? '');
        $isMinor = (strpos($lvl, 'MINOR') !== false);
        $isMajor = (strpos($lvl, 'MAJOR') !== false);
        if ($category === 'MINOR' && !$isMinor) continue;
        if (($category === 'MAJOR_SANCTIONS' || $category === 'MAJOR' || $category === 'SANCTIONS') && !$isMajor && empty($r['sanction'])) continue;
        if ($category === 'DISMISSED' && strpos(strtoupper($r['sanction'] ?? ''), 'DISMISS') === false) continue;

        $filtered[] = $r;
    }
    return $filtered;
}
